import{B,C,read,path,ray}from'../ten-utils.js';
export default({g,p,extra,t})=>{let m=extra.mode??0,k=p[0];if(m===0){g.line([0,-1,0],[0,1,0],C.white,5);if(k)ray(g,[0,k>0?.6:-.6,0],[0,k>0?-.6:.6,0]);if(k)for(let r of[.35,.65,.95]){path(g,Array.from({length:49},(_,i)=>[r*Math.cos(i*Math.PI/24),0,r*Math.sin(i*Math.PI/24)]),C.blue,1+.45*Math.abs(k));let a=t*.3*Math.sign(k);g.sphere(Math.cos(a)*r,0,Math.sin(a)*r,.035,C.gold)}return[read('Signed current','चिह्न सहित धारा',k,'A'),read('Relative field strength at fixed distance','नियत दूरी पर सापेक्ष क्षेत्र प्रबलता',Math.abs(k)),read('Magnetic field','चुंबकीय क्षेत्र',k===0?B('No current-produced field','धारा से उत्पन्न क्षेत्र नहीं'):B('Concentric circles; reversing current reverses direction','संकेंद्रित वृत्त; धारा उलटने पर दिशा उलटती है'))]}
if(m===1){let pts=Array.from({length:k*20+1},(_,i)=>{let f=i/(k*20),a=f*k*2*Math.PI;return[-1.1+2.2*f,Math.cos(a)*.35,Math.sin(a)*.35]});path(g,pts,C.gold,2);for(let y of[-.15,0,.15])ray(g,[-1.3,y,0],[1.3,y,0],C.blue);g.text(-1.2,-.65,0,'S');g.text(1.2,-.65,0,'N');return[read('Turns','फेरे',k),read('Relative internal field at fixed current and length','नियत धारा और लंबाई पर सापेक्ष आंतरिक क्षेत्र',fmt(k/4)),read('Pattern','रूप',B('Nearly parallel inside a long solenoid; end effects omitted','लंबी परिनालिका में भीतर लगभग समांतर; सिरों का प्रभाव नहीं दिखाया'))]}
for(let y of[-.6,0,.6])ray(g,[-1.3,y,0],[1.3,y,0],C.blue);g.line([0,-.8,0],[0,.8,0],C.white,5);if(k){ray(g,[0,k>0?.6:-.6,0],[0,k>0?-.6:.6,0],C.gold);ray(g,[0,0,0],[0,0,k*.18],C.pink)}return[read('Signed current','चिह्न सहित धारा',k,'A'),read('Relative force','सापेक्ष बल',Math.abs(k)),read('Direction','दिशा',k===0?B('No magnetic force from current','धारा के कारण चुंबकीय बल नहीं'):k>0?B('Out of diagram plane (+z)','चित्र के तल से बाहर (+z)'):B('Into diagram plane (−z)','चित्र के तल के भीतर (−z)'))]};const fmt=x=>String(Number(x.toFixed(2)));
